function trackUndoHistory(operations) {
    const stack = [];
    const result = [];
    for (const op of operations) {
        if (op === 'UNDO') {
            if (stack.length > 0) stack.pop();
        } else if (op === 'LAST') {
            result.push(stack.length === 0 ? 'NONE' : stack[stack.length - 1]);
        } else {
            const parts = op.split(' ');
            stack.push(parts[1]);
        }
    }
    return result.join(' ');
}
